import React, { useState, useEffect } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import axios from "axios";
import "./VoteCasting.css";

const VoteCasting = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [voting, setVoting] = useState(false);
  const [selectedCandidate, setSelectedCandidate] = useState(null);
  const [voteSuccess, setVoteSuccess] = useState(false);
  const [error, setError] = useState("");

  // Get user data from location state
  const userData = location.state?.userData;

  useEffect(() => {
    if (!userData) {
      navigate("/login");
      return;
    }
    fetchCandidates();
  }, [userData, navigate]);

  const fetchCandidates = async () => {
    try {
      const response = await axios.get("http://localhost:5000/api/candidates");
      setCandidates(response.data);
      setLoading(false);
    } catch (error) {
      console.error("Error fetching candidates:", error);
      setError("Failed to load candidates. Please try again.");
      setLoading(false);
    }
  };

  const handleVote = async (candidateId) => {
    if (!userData) {
      setError("User data not found. Please login again.");
      return;
    }

    setVoting(true);
    setError("");

    try {
      const response = await axios.post("http://localhost:5000/api/cast-vote", {
        userId: userData.id,
        candidateId: candidateId,
        aadharNumber: userData.aadhaarNumber,
        voterId: userData.voterId,
      });

      if (response.data.success) {
        setVoteSuccess(true);
        setSelectedCandidate(
          candidates.find((c) => c.id === candidateId)?.name
        );
        // Refresh candidates to update vote counts
        setTimeout(() => fetchCandidates(), 1000);
      }
    } catch (error) {
      console.error("Error casting vote:", error);
      setError(
        error.response?.data?.message ||
          "Failed to cast vote. Please try again."
      );
    } finally {
      setVoting(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("userToken");
    navigate("/login");
  };

  if (loading) {
    return (
      <div className="vote-casting-background">
        <div className="loading">Loading candidates...</div>
      </div>
    );
  }

  if (voteSuccess) {
    return (
      <div className="vote-casting-background">
        <div className="vote-success-container">
          <div className="vote-success-card">
            <div className="success-icon">✅</div>
            <h2>Vote Cast Successfully!</h2>
            <p>Thank you for voting in the election.</p>
            {selectedCandidate && (
              <div className="vote-details">
                <p>
                  <strong>You voted for:</strong> {selectedCandidate}
                </p>
              </div>
            )}
            <button onClick={handleLogout} className="logout-btn">
              🚪 Logout
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="vote-casting-background">
      <div className="vote-casting-container">
        <div className="vote-casting-card">
          <div className="vote-header">
            <h1>🗳️ Cast Your Vote</h1>
            <p>Please select your preferred candidate</p>
            <button onClick={handleLogout} className="logout-btn-header">
              🚪 Logout
            </button>
          </div>

          {error && <div className="error-message">{error}</div>}

          {userData && (
            <div className="user-info">
              <h3>Voter Information</h3>
              <p>
                <strong>Name:</strong> {userData.name}
              </p>
              <p>
                <strong>Voter ID:</strong> {userData.voterId}
              </p>
              <p>
                <strong>Aadhar:</strong> {userData.aadhaarNumber}
              </p>
            </div>
          )}

          <div className="candidates-list">
            <h3>🏆 Candidates List</h3>
            {candidates.length === 0 ? (
              <div className="no-candidates">
                <p>No candidates available for voting.</p>
                <p>Please check back later.</p>
              </div>
            ) : (
              <div className="candidates-grid">
                {candidates.map((candidate) => (
                  <div key={candidate.id} className="candidate-card">
                    <div className="candidate-info">
                      <h4>{candidate.name}</h4>
                      <p className="party">{candidate.party}</p>
                      {candidate.symbol && (
                        <p className="symbol">{candidate.symbol}</p>
                      )}
                      <p className="votes">
                        Votes: <strong>{candidate.votes || 0}</strong>
                      </p>
                    </div>
                    <button
                      onClick={() => handleVote(candidate.id)}
                      disabled={voting}
                      className="vote-btn"
                    >
                      {voting ? "🔄 Voting..." : "✅ Vote"}
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>

          <div className="voting-instructions">
            <h4>📋 Voting Instructions</h4>
            <ul>
              <li>✓ You can vote for only one candidate</li>
              <li>✓ Once voted, you cannot change your vote</li>
              <li>✓ Multiple voting is strictly prohibited</li>
              <li>✓ Your vote is anonymous and secure</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default VoteCasting;
